from ortools.sat.python import cp_model

def solve_problem():
    model = cp_model.CpModel()
    n = 8
    m = 56  # number of white markers
    board = [[model.NewIntVar(0, 1, f'white_{i}_{j}') for j in range(n)] for i in range(n)]
    for i in range(n):
        for j in range(n):
            model.Add(board[i][j] <= 1)  # each cell can contain at most one white marker
    moves = []
    for i in range(n):
        for j in range(n):
            for k in range(n):
                for d in range(n):
                    if (i != k or j != d) and (abs(i - k) + abs(j - d) == 1 or i == k and j == d):  # valid move
                        moves.append((i + 1, j + 1, k + 1, d + 1))  # move marker from (i,j) to (k,d)
    model.Maximize(len(moves))  # maximize the number of valid moves
    solver = cp_model.CpSolver()
    status = solver.Solve(model)
    if status == cp_model.FEASIBLE:
        solution = []
        for i in range(n):
            for j in range(n):
                if solver.Value(board[i][j]) == 1:  # if there is a white marker at (i,j)
                    solution.append((i + 1, j + 1))  # add it to the initial configuration
        colored_markers = []
        for i in range(n):
            for j in range(n):
                if solver.Value(board[i][j]) == 1:  # if there is a white marker at (i,j)
                    colored_markers.append(moves[i * n + j])  # add the move to color it black
        return (solution, colored_markers)
    else:
        return None

result = solve_problem()
